addressee.value:
(function()
{
   try {
  		var vEmpresa=IDVault.get(initiator , 'user', 'midSAP-user-empresa');
            return 'CN=GRP-'  +  vEmpresa + '-UNLK-APROVADOR,OU=GRUPOS,O=mid';
   } catch (error) {
		return 'CN=UserApp37,O=mid';
  }

})()

user-activity.addressee:
(function()
                                                    {
                                                    try {
                                                    var vEmpresa=IDVault.get(initiator , 'user',
                                                    'midSAP-user-empresa');
                                                    return 'CN=GRP-' + vEmpresa +
                                                    '-UNLK-APROVADOR,OU=GRUPOS,O=mid';
                                                    } catch (error) {
                                                    return 'CN=UserApp37,O=mid';
                                                    }
                                                    
                                                    })()

log-activity.message:
function retornaMSG() {
                                                    
                                                    var MSG;
                                                    if(flowdata.get('Start/request_form/Acao') ==
                                                    'false') MSG = "Ação / Action: Bloquear usuário
                                                    / Lock User.";
                                                    else MSG = "Ação / Action: Desbloquear usuário /
                                                    Unlock User."
                                                    
                                                    return MSG;
                                                    }
                                                    retornaMSG();

